// wisp-design — Browser-side sanitisation (Phase 2).
//
// Implements `SanitizeModule` from src/contracts/browser.ts. Pure functions,
// no shared mutable state, browser-only (NO node-imports, NO DOM-reads).
// Hand-rolled, not DOMPurify — the live.js bundle has a 50 kB budget and we
// only need a narrow surface (textContent escape, free-text scrub, CSS-var
// value gate, selector gate).
//
// Trust boundary: every string a user or agent influences flows through this
// module before reaching innerHTML, element.style, querySelector, or the
// injected `<style data-wisp-css>` block. See docs/browser-runtime.md
// § "Security Layer".
//
// Spec source: src/contracts/browser.ts `SanitizeModule`,
//              docs/browser-runtime.md "Forbidden in any sanitised string".

// Value-import from the browser-local constants module — NOT contracts.
// Importing FREE_TEXT_MAX_LEN from "../contracts/browser.js" would force
// evaluation of that module's top-level `z.object(...)` schemas and inline
// the entire zod runtime into the IIFE bundle (~41 kB cost, blew the 50 kB
// live.js budget). Type-only imports below stay on contracts because they
// erase at compile time. See src/browser/constants.ts header.
import { FREE_TEXT_MAX_LEN } from "./constants.js";
import type {
  SanitizeError,
  SanitizeFreeTextOptions,
  SanitizeModule,
  SanitizeReason,
} from "../contracts/browser.js";

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function sanitizeError(
  code: SanitizeReason,
  message: string,
  detail?: unknown,
): SanitizeError {
  return detail !== undefined ? { code, message, detail } : { code, message };
}

// HTML entities. Single-quote uses numeric reference (`&#39;`) because
// `&apos;` is not in HTML4 — numeric is universally understood.
const HTML_ESCAPE_MAP: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};
const HTML_ESCAPE_RE = /[&<>"']/g;

// C0 control characters U+0000..U+001F EXCEPT \t \n \r (which `sanitizeFreeText`
// preserves so multi-line notes survive). U+007F (DEL) is also stripped — it
// commonly slips in from clipboard paste of legacy text and serves no
// rendering purpose.
const CONTROL_CHAR_RE = /[�--]/g;

// Script/style blocks: greedy `<tag>` opener + lazy `[\s\S]*?` body + `</tag>`
// closer. `[\s\S]` is required because `.` doesn't match newlines without the
// `s` flag, and we want the regex to stay portable to ES2020-target bundles.
const SCRIPT_BLOCK_RE = /<script\b[^>]*>[\s\S]*?<\/script\s*>/gi;
const STYLE_BLOCK_RE = /<style\b[^>]*>[\s\S]*?<\/style\s*>/gi;

// Container tags that frequently host script-injection or sandbox-escape
// payloads. We strip the whole open-to-close range (including unclosed
// variants — see the "no-close" branch below).
const CONTAINER_TAGS = ["iframe", "object", "embed", "svg"] as const;

// Inline event-handler attribute scrubber. Matches a leading whitespace char
// to avoid eating part of a preceding attribute name (e.g. `name=` near a
// `on*=` would otherwise collapse). The value alternation covers
// double-quoted, single-quoted, and unquoted forms.
const INLINE_EVENT_HANDLER_RE = /\son\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi;

// Dangerous URL prefixes. Stripped (not the whole attribute) so a benign tail
// like `alert(1)` remains as plain text — matches the documented expectation
// `sanitizeFreeText("javascript:alert(1)") === "alert(1)"`. Strip-prefix was
// chosen over reject-whole because freeText is a description field; users may
// legitimately type "see javascript:foo bar" and lose only the prefix.
const URL_PREFIX_RE = /\b(?:javascript|data|vbscript)\s*:/gi;

// ---------------------------------------------------------------------------
// 1. escapeHtml — textContent-safe HTML escape.
// ---------------------------------------------------------------------------

export function escapeHtml(s: string): string {
  // Defensive: non-string input → empty for nullish, String() cast otherwise.
  // Returning "" for NaN / null / undefined is documented behaviour and
  // matches the floating-bar's "no text" rendering branch.
  if (s === null || s === undefined) return "";
  if (typeof s === "number" && Number.isNaN(s)) return "";
  const str = typeof s === "string" ? s : String(s);
  return str.replace(HTML_ESCAPE_RE, (ch) => HTML_ESCAPE_MAP[ch] ?? ch);
}

// ---------------------------------------------------------------------------
// 2. sanitizeFreeText — agent / user free-text input scrubber.
//    NOT an HTML-escape (pair with escapeHtml at the rendering site).
//    Goal: strip script-injection vectors and normalise to a length cap.
// ---------------------------------------------------------------------------

function stripContainerTags(input: string): string {
  let out = input;
  for (const tag of CONTAINER_TAGS) {
    // Pair-matched open/close (most common shape).
    const paired = new RegExp(`<${tag}\\b[^>]*>[\\s\\S]*?<\\/${tag}\\s*>`, "gi");
    out = out.replace(paired, "");
    // Self-closing / unclosed variants — strip the opener so even malformed
    // input doesn't leak a partial tag through. Attackers truncating to skip
    // the close-tag is a real bypass; this neutralises it.
    const orphanOpen = new RegExp(`<${tag}\\b[^>]*\\/?>`, "gi");
    out = out.replace(orphanOpen, "");
    // Stray closer in case the input was a fragment.
    const orphanClose = new RegExp(`<\\/${tag}\\s*>`, "gi");
    out = out.replace(orphanClose, "");
  }
  return out;
}

function truncateOnWordBoundary(s: string, maxLen: number): string {
  if (s.length <= maxLen) return s;
  const hardCut = s.slice(0, maxLen);
  // Prefer the last whitespace within the cut window, but only if it's
  // "close enough" — otherwise we'd truncate a long URL to nothing useful.
  // Threshold: at least 75% of maxLen. Below that, fall back to hard cut.
  const lastSpace = hardCut.search(/\s\S*$/);
  if (lastSpace !== -1 && lastSpace >= Math.floor(maxLen * 0.75)) {
    return hardCut.slice(0, lastSpace);
  }
  return hardCut;
}

export function sanitizeFreeText(
  s: string,
  opts?: SanitizeFreeTextOptions,
): string {
  if (s === null || s === undefined) return "";
  const raw = typeof s === "string" ? s : String(s);
  const maxLen =
    opts && typeof opts.maxLen === "number" && opts.maxLen > 0
      ? Math.floor(opts.maxLen)
      : FREE_TEXT_MAX_LEN;

  // 1. Newline normalisation FIRST so subsequent regexes see one form.
  //    `\r\n` → `\n`, lone `\r` → `\n`.
  let out = raw.replace(/\r\n/g, "\n").replace(/\r/g, "\n");

  // 2. Strip whole script / style blocks. Order matters: do this BEFORE the
  //    container-tag pass so a `<script>` inside a `<svg>` is double-stripped
  //    rather than partially leaked.
  out = out.replace(SCRIPT_BLOCK_RE, "");
  out = out.replace(STYLE_BLOCK_RE, "");

  // 3. Strip container tags (iframe / object / embed / svg) including
  //    unclosed openers — sandbox-escape vectors.
  out = stripContainerTags(out);

  // 4. Strip inline event handlers (`onclick=…`, `onerror=…`, etc.). We do
  //    this AFTER container-strip so a `<svg onload=…>` was already removed,
  //    but BEFORE URL-prefix-strip so `<a href=javascript:…>` still has its
  //    `javascript:` neutralised when the surrounding tag survives (e.g. a
  //    bare `<a>` we don't blanket-strip).
  out = out.replace(INLINE_EVENT_HANDLER_RE, "");

  // 5. Strip dangerous URL prefixes anywhere in the string.
  //    Decision: strip-prefix (not reject-whole). Rationale: this function
  //    cleans text, not validates intent — the tail content may carry the
  //    actual semantic value the user typed. The bridge's stricter validators
  //    (trustedCssVar / trustedSelector) DO reject-whole.
  out = out.replace(URL_PREFIX_RE, "");

  // 6. Strip C0 control characters (except \t \n \r, preserved for layout).
  out = out.replace(CONTROL_CHAR_RE, "");

  // 7. Length cap. We measure UTF-16 code units (string `.length`) — same
  //    metric the bridge uses on `ConfigureEventSchema`. If you change one,
  //    change both (search FREE_TEXT_MAX_LEN).
  out = truncateOnWordBoundary(out, maxLen);

  return out;
}

// ---------------------------------------------------------------------------
// 3. trustedCssVar — CSS custom-property assignment gate.
//    Called before `element.style.setProperty(varName, value)`.
// ---------------------------------------------------------------------------

// Contract regex: must start `--`, lowercase-alpha first body char, then
// `[a-z0-9-]*`. Case-insensitive per the regex flag. Length cap 64 chars
// matches the prompt brief; the regex itself doesn't bound length so we check
// separately.
const CSS_VAR_NAME_RE = /^--[a-z][a-z0-9-]*$/i;
const CSS_VAR_NAME_MAX = 64;

// Substrings that must never appear in a value. Case-insensitive. Each blocks
// a specific attack vector:
//   - url(           — external resource load (exfiltration, mixed content)
//   - @import        — CSS-injected stylesheet
//   - expression(    — legacy IE CSS expressions (RCE on old browsers; still
//                      present in some embedded webviews)
//   - javascript:    — `cursor: url(javascript:…)` and similar oddities
//   - data:          — inline data URIs (XSS via SVG-in-data-URI)
//   - vbscript:      — legacy IE script protocol
const FORBIDDEN_CSS_SUBSTRINGS = [
  "url(",
  "@import",
  "expression(",
  "javascript:",
  "data:",
  "vbscript:",
] as const;

// Single chars that would let an attacker escape the CSS-var assignment
// context:
//   ;  → terminate the declaration and inject a new one
//   {  → open a new rule block
//   }  → close the current block early
//   <  → script-injection via `<style>` content (paranoid)
//   >  → ditto
//   \  → CSS escape sequences (`\0022` etc.) — too many bypass paths
const FORBIDDEN_CSS_CHARS = [";", "{", "}", "<", ">", "\\"] as const;
const CSS_VAR_VALUE_MAX = 256;

export function trustedCssVar(
  varName: string,
  value: string,
):
  | { ok: true; varName: string; value: string }
  | { ok: false; reason: SanitizeError } {
  if (typeof varName !== "string" || varName.length === 0) {
    return {
      ok: false,
      reason: sanitizeError("INVALID_CSS_VAR_NAME", "var name must be a non-empty string"),
    };
  }
  if (varName.length > CSS_VAR_NAME_MAX) {
    return {
      ok: false,
      reason: sanitizeError(
        "INVALID_CSS_VAR_NAME",
        `var name exceeds ${CSS_VAR_NAME_MAX} chars`,
        { length: varName.length },
      ),
    };
  }
  if (!CSS_VAR_NAME_RE.test(varName)) {
    return {
      ok: false,
      reason: sanitizeError(
        "INVALID_CSS_VAR_NAME",
        "var name must match /^--[a-z][a-z0-9-]*$/i",
        { varName },
      ),
    };
  }

  if (typeof value !== "string" || value.length === 0) {
    return {
      ok: false,
      reason: sanitizeError("INVALID_CSS_VALUE", "value must be a non-empty string"),
    };
  }
  if (value.length > CSS_VAR_VALUE_MAX) {
    return {
      ok: false,
      reason: sanitizeError(
        "INVALID_CSS_VALUE",
        `value exceeds ${CSS_VAR_VALUE_MAX} chars`,
        { length: value.length },
      ),
    };
  }

  const lower = value.toLowerCase();
  for (const sub of FORBIDDEN_CSS_SUBSTRINGS) {
    if (lower.includes(sub)) {
      return {
        ok: false,
        reason: sanitizeError("INVALID_CSS_VALUE", `forbidden substring \`${sub}\``, {
          substring: sub,
        }),
      };
    }
  }
  for (const ch of FORBIDDEN_CSS_CHARS) {
    if (value.includes(ch)) {
      return {
        ok: false,
        reason: sanitizeError("FORBIDDEN_CHAR", `forbidden character \`${ch}\``, {
          char: ch,
        }),
      };
    }
  }
  // Reject control chars in CSS values outright — no legitimate need.
  if (CONTROL_CHAR_RE.test(value) || /[\n\r\t]/.test(value)) {
    return {
      ok: false,
      reason: sanitizeError("FORBIDDEN_CHAR", "control characters not allowed in CSS values"),
    };
  }

  return { ok: true, varName, value };
}

// ---------------------------------------------------------------------------
// 4. trustedSelector — CSS-selector gate for `document.querySelector`.
//    For selectors we DIDN'T construct ourselves — i.e. anything originating
//    from agent or user payloads.
// ---------------------------------------------------------------------------

// Substrings / patterns that indicate the selector is trying to do more than
// "match an element". Each entry is checked in lowercase.
const FORBIDDEN_SELECTOR_SUBSTRINGS = [
  "<",
  ">", // angle brackets aren't valid in selectors anyway
  "script",
  "style",
  "}",
  "{",
  ";",
  "\\",
  "*=",
  "@",
] as const;

const SELECTOR_MAX = 1024;

// `:has(...)` is powerful; abuse it to nest dangerous selectors. We allow
// `:has(.foo)` but reject `:has(iframe)` or `:has(script)`. Detected by
// scanning the contents of any `:has( … )` group for blacklisted tokens.
const HAS_CLAUSE_RE = /:has\s*\(([^)]*)\)/gi;
const HAS_INNER_FORBIDDEN_RE = /\b(?:script|iframe|object|embed|svg|on\w+)\b/i;

export function trustedSelector(
  sel: string,
):
  | { ok: true; selector: string }
  | { ok: false; reason: SanitizeError } {
  if (typeof sel !== "string") {
    return {
      ok: false,
      reason: sanitizeError("INVALID_SELECTOR", "selector must be a string"),
    };
  }
  const trimmed = sel.trim();
  if (trimmed.length === 0) {
    return { ok: false, reason: sanitizeError("EMPTY", "selector is empty") };
  }
  if (trimmed.length > SELECTOR_MAX) {
    return {
      ok: false,
      reason: sanitizeError("TOO_LONG", `selector exceeds ${SELECTOR_MAX} chars`, {
        length: trimmed.length,
      }),
    };
  }

  // Newline in selectors is benign per CSS spec but indicates the input is
  // probably not a selector at all (it's a free-form payload).
  if (/[\n\r]/.test(trimmed)) {
    return {
      ok: false,
      reason: sanitizeError("INVALID_SELECTOR", "selector must not contain newlines"),
    };
  }

  const lower = trimmed.toLowerCase();
  for (const sub of FORBIDDEN_SELECTOR_SUBSTRINGS) {
    if (lower.includes(sub)) {
      return {
        ok: false,
        reason: sanitizeError("INVALID_SELECTOR", `forbidden substring \`${sub}\``, {
          substring: sub,
        }),
      };
    }
  }

  // URL-prefix paranoia — selectors shouldn't ever contain protocol strings.
  if (/(javascript|data|vbscript)\s*:/i.test(trimmed)) {
    return {
      ok: false,
      reason: sanitizeError("INVALID_SELECTOR", "selector contains URL protocol prefix"),
    };
  }

  // `:has(...)` deep-check. Run after the substring-blacklist so the simple
  // case is fast. We iterate all `:has(...)` groups to handle multiples.
  HAS_CLAUSE_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = HAS_CLAUSE_RE.exec(trimmed)) !== null) {
    const inner = match[1] ?? "";
    if (HAS_INNER_FORBIDDEN_RE.test(inner)) {
      return {
        ok: false,
        reason: sanitizeError(
          "INVALID_SELECTOR",
          ":has() contains forbidden token",
          { inner },
        ),
      };
    }
  }

  return { ok: true, selector: trimmed };
}

// ---------------------------------------------------------------------------
// Aggregate — single import surface for the rest of the browser bundle.
// ---------------------------------------------------------------------------

export const sanitizeModule: SanitizeModule = {
  escapeHtml,
  sanitizeFreeText,
  trustedCssVar,
  trustedSelector,
};
